import java.util.*;

public class Perturbed1 {
    static final int MOD = 998244353;
    static PrintWriter out;

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        out = new PrintWriter(System.out);
        int n = sc.nextInt();
        long k = sc.nextLong();
        if (k >= n) {
            out.println(0);
            out.flush();
            return;
        }
        long[] fac = new long[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % MOD;
        }
        if (k == 0) {
            out.println(fac[n]);
            out.flush();
            return;
        }
        int c = n - (int) k;
        long ans = fac[n] * modPow(fac[c], MOD - 2) % MOD;
        ans = ans * modPow(fac[n - c], MOD - 2) % MOD;
        long tem = 0;
        for (int i = 0; i <= c; i++) {
            long comb = fac[c] * modPow(fac[i], MOD - 2) % MOD;
            comb = comb * modPow(fac[c - i], MOD - 2) % MOD;
            long term = comb * modPow(c - i, n) % MOD;
            if ((i & 1) == 0) {
                tem = (tem + term) % MOD;
            } else {
                tem = (tem - term + MOD) % MOD;
            }
        }
        ans = ans * tem % MOD * 2 % MOD;
        out.println(ans);
        out.flush();
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}
